pub enum Msg {
    Ping,
    Hello(String),
    Heartbeat(u32),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    if bytes.contains("ping") {
        return Ok(Msg::Ping);
    }
    if let Some(body) = bytes.strip_prefix("{\"v\":2,\"hello\":\"") {
        if let Some(body) = body.strip_suffix("\"}") {
            return Ok(Msg::Hello(body.into()));
        }
    }
    if let Some(body) = bytes.strip_prefix("{\"v\":2,\"heartbeat\":") {
        if let Some(sequence) = body.strip_suffix('}') {
            if let Ok(sequence) = sequence.parse() {
                return Ok(Msg::Heartbeat(sequence));
            }
        }
    }
    Err("unknown".into())
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "ping".into(),
        Msg::Hello(value) => format!(r#"{{"v":2,"hello":"{}"}}"#, value),
        Msg::Heartbeat(sequence) => format!(r#"{{"v":2,"heartbeat":{}}}"#, sequence),
    }
}

pub fn ping_roundtrip() -> Result<Msg, String> {
    decode(&encode(&Msg::Ping))
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_ping_frame() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn roundtrips_hello_frame() {
        let encoded = encode(&Msg::Hello("Ada".into()));
        assert_eq!(encoded, r#"{"v":2,"hello":"Ada"}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Hello(name)) if name == "Ada"));
    }

    #[test]
    fn roundtrips_heartbeat_frame() {
        let encoded = encode(&Msg::Heartbeat(42));
        assert_eq!(encoded, r#"{"v":2,"heartbeat":42}"#);
        assert!(matches!(decode(&encoded), Ok(Msg::Heartbeat(sequence)) if sequence == 42));
    }
}
